  ('20260000-0000-4000-8000-000000000001', '2026-elocution', 1, 'Speak to the Stars', null, array['Individual participation only.', 'The topic will be given on the spot.', 'Time limit: minimum 3 minutes, maximum 5 minutes.', 'No vulgar, abusive, offensive, political, or discriminatory content.', 'Reporting time: 20 minutes before the event starts.']::text[], null, false, '/Elocution.jpg', 'Elocution thumbnail', 'Elocution', 'Speak to the Stars', null, null, null, 'Elocution', 'TBA', 'General', null, 'none', null, 'draft', false, 1),
  ('20260000-0000-4000-8000-000000000002', '2026-ff-final-zone-arena', 1, 'Final Zone Arena', null, array['A team must have 4+1 players. Each team must have a team name.', 'Teaming up with students from other departments is strictly not allowed.', 'No WiFi and no charging points will be provided.', 'Only mobile phones are allowed. No iPad, tablet, or emulator.', 'Each qualification round has 3 matches. Room ID and password will be given before each match.', 'Any player found cheating will result in disqualification of the team.', 'At least 2 members must record their POV, and screenshots (SS) are mandatory.', 'Points: 1st rank 10, 2nd rank 9, 3rd rank 8, 4th rank 7, 5th rank 6, 6th rank 5, 7th rank 4, 8th rank 3. Per kill: 1 point.']::text[], 'https://chat.whatsapp.com/JvUiz9gX6E5EAoFA3G9mfi', false, '/ff%20zone%20arena.jpg', 'FF (Final Zone Arena) thumbnail', 'FF (Final Zone Arena)', 'Final Zone Arena', null, null, null, 'FF (Final Zone Arena)', 'TBA', 'General', null, 'none', null, 'draft', false, 2),
  ('20260000-0000-4000-8000-000000000003', '2026-mehndi', 1, 'Starlit Hands', null, array['Participants must bring their own natural mehndi cones and materials. Chemical colours, glitter, stickers, or stencils are generally prohibited.', 'Duration: 1 hour.', 'Designs must cover one hand, including the palm side and the back of the hand up to the elbow.', 'Designs must be original and creative. No printed materials, phones, or references are allowed once the competition begins.', 'Participants may apply mehndi on their own hand or on a model''s hand that they bring themselves.', 'Breaking any rule, including using prohibited materials or excessive tardiness, may lead to disqualification.']::text[], 'https://chat.whatsapp.com/KZFyGt6qKCNJK2cy19Go41', false, '/menhindi.jpg', 'Mehndi thumbnail', 'Mehndi', 'Starlit Hands', null, null, null, 'Mehndi', 'TBA', 'General', null, 'none', null, 'draft', false, 3),
  ('20260000-0000-4000-8000-000000000004', '2026-dance-solo', 1, 'Cosmic Choreography', null, array['Maximum performance time: 3 minutes.', 'Audio quality must be 320 kbps or 256 kbps. Audio format must be MP3.', 'Audio must be submitted at least 5 days before the event day. No end-moment changes are allowed.', 'Props are allowed but must be handled by the participant only.', 'Stunts (fire, glass, flips, etc.) are strictly prohibited.']::text[], 'https://chat.whatsapp.com/KULDg4U0Lqp2Jr5S16cbTh', false, '/solo%20dance.jpg', 'Dance - Solo thumbnail', 'Dance - Solo', 'Cosmic Choreography', null, null, null, 'Dance - Solo', 'TBA', 'General', null, 'none', null, 'draft', false, 4),
  ('20260000-0000-4000-8000-000000000005', '2026-dance-group', 1, 'Cosmic Choreography', null, array['Each team must have a maximum of 8 members.', 'Maximum performance time: 5 minutes.', 'Audio quality must be 320 kbps or 256 kbps. Audio format must be MP3.', 'Audio must be submitted at least 5 days before the event day. No end-moment changes are allowed.', 'Props are allowed but must be handled by the participants only.', 'Stunts (fire, glass, flips, etc.) are strictly prohibited.']::text[], 'https://chat.whatsapp.com/CxHt2lJT8Yr3iPE5B2w6tq', false, '/group%20dance.jpg', 'Dance - Group thumbnail', 'Dance - Group', 'Cosmic Choreography', null, null, null, 'Dance - Group', 'TBA', 'General', null, 'none', null, 'draft', false, 5),
  ('20260000-0000-4000-8000-000000000006', '2026-ramp-walk', 1, 'Face of Galaxia', null, array['Duration: 3 minutes.', 'Participants must bring their own music track (MP3). Audio must be submitted at least 5 days before the event day.', 'Costumes, choreography, and presentation must be creative and beyond the imagination.', 'Props are allowed, except hazardous items such as fire, water, or glitter bombs.', 'Every participant must report 30 minutes before the event for registration and sound check.']::text[], null, false, '/ramp%20walk.jpg', 'Ramp Walk thumbnail', 'Ramp Walk', 'Face of Galaxia', null, null, null, 'Ramp Walk', 'TBA', 'General', null, 'none', null, 'draft', false, 6),
  ('20260000-0000-4000-8000-000000000007', '2026-box-cricket', 1, 'Boundary Breakers', null, array['A team has 8+1 players. The extra 1 player is compulsory.', 'Each team is given 2 overs per match. 3 overs are given in the semi-final and final only.', 'No sidearm action is allowed.', 'One bowler bowls one over (mandatory).', 'In case of a tie, there is no super over or replay. The result will be decided as per the tournament organisers'' rules.', 'Team members cannot be changed after registration until the end of the competition.', 'Participants must bring their own bats.', 'Strict action will be taken for arguing with referees. The referee''s decision is final.', 'Changes in rules, schedule, or draws are at the discretion of the WCCBM sports committee.']::text[], 'https://chat.whatsapp.com/GoWj1wgz5YJEWgpPaNb2an', false, '/box%20cricket.jpg', 'Box Cricket thumbnail', 'Box Cricket', 'Boundary Breakers', null, null, null, 'Box Cricket', 'TBA', 'General', null, 'none', null, 'draft', false, 7),
  ('20260000-0000-4000-8000-000000000008', '2026-carom', 1, 'Orbit Strike', null, array['Singles and doubles categories will be played.', 'Only one board will be played per match. Best of 3 boards for the semi-final and final only.', 'Taping is considered a foul.', 'Every player must carry their own striker.', 'General carom rules will apply.', 'Changes in rules, schedule, or draws are at the discretion of the WCCBM sports committee.']::text[], 'https://chat.whatsapp.com/LWdjh6gWPD57ZhARxiuo7C', false, '/carrom.jpg', 'Carom thumbnail', 'Carom', 'Orbit Strike', null, null, null, 'Carom', 'TBA', 'General', null, 'none', null, 'draft', false, 8),
  ('20260000-0000-4000-8000-000000000009', '2026-football', 1, '', null, array['5 players per side (5-a-side). 2 rolling substitutes.', 'Duration: 10 minutes + 2 minute break + 10 minutes.', 'The referee''s decision is final.', 'Lots and draws are finalised only by the organising committee.', 'Team members cannot be changed after registration until the end of the competition.', 'Changes in rules, schedule, or draws are at the discretion of the WCCBM sports committee.']::text[], null, false, '/vollyball%20male.jpg', 'Football thumbnail', 'Football', '', null, null, null, 'Football', 'TBA', 'General', null, 'none', null, 'draft', false, 9),
  ('20260000-0000-4000-8000-000000000010', '2026-body-posing', 1, 'Titans of Anantara or Galaxia', null, array['Two height categories: up to 170 cm, and 170 cm and above.', 'Top 2 athletes in each category receive a trophy, cash prize, and certificate. 3rd place receives a medal and certificate.', 'College ID is compulsory.', 'Shorts must follow the standard rules of Mr. Physique. Board shorts must not be lower than 2 inches above the knees. Any pattern or colour is acceptable, but no commercial branding or advertising is allowed. Bring shorts to event check-in for inspection.', 'Except for a wedding ring, competitors may not wear footwear, glasses, watches, pendants, earrings, wigs, or distracting ornamentation.', 'Implants or fluid injections that change the natural shape of the body are strictly prohibited and may result in disqualification.', 'Props are strictly prohibited during prejudging or the finals presentation.', 'A category runs only if it has at least 5 athletes. If not, it is combined with the next taller class where possible. If the tallest category has fewer than 5, it is combined with the closest shorter class. If still fewer than 5, more categories are combined, or eventually one open class is run.', 'Changes in rules, schedule, or draws are at the discretion of the WCCBM sports committee.']::text[], 'https://chat.whatsapp.com/LJukQmm5exR7XZb1eDLsO6', false, '/body%20posing.jpg', 'Body Posing thumbnail', 'Body Posing', 'Titans of Anantara or Galaxia', null, null, null, 'Body Posing', 'TBA', 'General', null, 'none', null, 'draft', false, 10),
  ('20260000-0000-4000-8000-000000000011', '2026-stalk-the-stock', 1, '', null, array['Category 1: intraday stock trading. Category 2: futures and options (F&O). Category 3: Other (details to be confirmed).', 'In Categories 1 and 2, participants may place up to 10 trades per category. Every buy or sell order counts as one trade.', 'Rules, fee, and scoring for Category 3 (Other) are to be confirmed.', 'For intraday stocks and F&O, the participant with the highest portfolio value wins.', 'Trading is intraday only. Do not hold positions overnight. Automated tools and bots are not allowed.', 'The same prize schedule applies to all three categories. Any tie will be handled at the event venue.', 'The trading platform and virtual starting capital have not been declared yet.']::text[], null, false, '/stock%20the%20shock.jpg', 'Stalk the Stock thumbnail', 'Stalk the Stock', '', null, null, null, 'Stalk the Stock', 'TBA', 'General', null, 'none', null, 'draft', false, 11),
  ('20260000-0000-4000-8000-000000000012', '2026-case-toh-banta-hai', 1, '', null, array['Choose one case study from the 10 provided.', 'Make a PowerPoint presentation explaining your analysis and solution.', 'Maximum 15 slides. Exceeding 15 slides results in disqualification.', 'Presentation time: 10 minutes. If a team goes over time, marks may be deducted and a penalty applies (the exact penalty is not stated).', 'Plagiarism up to 15% is allowed. More than 15% results in negative marking.', 'Submit the PowerPoint through Unstop. The submission deadline is not provided yet (8 December 2026 is unconfirmed).', 'Judging: clarity and structure 30%, depth of analysis 30%, creativity and innovation 20%, practicality 20%.']::text[], 'https://chat.whatsapp.com/CwUoMqlgLRPAp8cIbs789E', false, '/case%20tho%20banta%20hai.jpg', 'Case Toh Banta Hai thumbnail', 'Case Toh Banta Hai', '', null, null, null, 'Case Toh Banta Hai', 'TBA', 'General', null, 'none', null, 'draft', false, 12),
  ('20260000-0000-4000-8000-000000000013', '2026-into-the-adverse', 1, '', null, array['Submit one creative photo and one advertisement reel of 10 to 25 seconds. Both must use the same idea or message.', 'You may show the product or leave it unseen, but viewers must understand the message.', 'Follow the assigned topic, which may focus on a product or an idea.', 'AI-generated visuals, downloaded photos or videos, and copyrighted music are not allowed.', 'Do not include vulgar, hateful, violent, offensive, or unsafe content.', 'The submission deadline is the event day.', 'A surprise creative challenge may take place on the event day. Its task and details are still to be decided.', 'Judging considers creativity, clarity of message, visual quality, originality, and how well the advertisement communicates its idea. Scoring weights are not stated.']::text[], 'https://chat.whatsapp.com/IP0fNXq97q1HxwvZZfBepk', false, '/into%20the%20advise.jpg', 'Into the Adverse thumbnail', 'Into the Adverse', '', null, null, null, 'Into the Adverse', 'TBA', 'General', null, 'none', null, 'draft', false, 13),
