  ('20260000-0000-4000-8000-000000000016', '2026-singing', 2, 'Echo of Orbit', null, array['Participants must register before the deadline.', 'Performance time: 2 to 3 minutes. A buzzer sounds in the last 20 seconds.', 'Audio quality must be 320 kbps or 256 kbps (if any audio is used).', 'Prior notice is required to use any instrument (guitar, tabla, dhol, keyboard, etc.) during the performance.', 'Audio must be submitted at least 3 days before the event day. No end-moment changes are allowed.']::text[], 'https://chat.whatsapp.com/KFQ1LdHAcHh23DN78WwjT3', false, '/singing.jpg', 'Singing thumbnail', 'Singing', 'Echo of Orbit', null, null, null, 'Singing', 'TBA', 'General', null, 'none', null, 'draft', false, 3),
