  ('20260000-0000-4000-8000-000000000019', '2026-volleyball', 2, 'Gravity Smash', null, array['A squad has 12 players (6 playing and 6 substitutes).', 'Only bonafide college students with a valid ID card are allowed.', 'Matches are best of 3 sets, played as per International Volleyball Federation (IVF) rules.', 'Walkover if a team does not report within 15 minutes of the scheduled time.', 'No player can play for two colleges or two teams.', 'Changes in rules, schedule, or draws are at the discretion of the WCCBM sports committee.']::text[], 'https://chat.whatsapp.com/DjFOJkSEfDFJHKeT4ld8sX', false, '/vollyball%20male.jpg', 'Volleyball thumbnail', 'Volleyball', 'Gravity Smash', null, null, null, 'Volleyball', 'TBA', 'General', null, 'none', null, 'draft', false, 6),
  ('20260000-0000-4000-8000-000000000020', '2026-bgmi', 2, 'Space Battle', null, array['A team must have 4+1 players. Each team must have a team name.', 'Teaming up with students from other departments is strictly not allowed.', 'Teams or squads must sit together.', 'No WiFi and no charging points will be provided.', 'Only mobile phones are allowed. No iPad, tablet, or emulator.', '3 matches will be played. Room ID and password will be given before each match.', 'Abusive language is strictly prohibited during the game.', 'Any player found cheating will result in disqualification of the team.', 'At least 2 members must record their POV, and screenshots (SS) are mandatory.', 'Points: 1st rank 10, 2nd rank 6, 3rd rank 5, 4th rank 4, 5th rank 3, 6th rank 2, 7th rank 1, 8th rank 1. Per kill: 1 point.']::text[], 'https://chat.whatsapp.com/FwBRyZgTjowAyDwFCIuajn', false, '/bgmi.jpg', 'BGMI thumbnail', 'BGMI', 'Space Battle', null, null, null, 'BGMI', 'TBA', 'General', null, 'none', null, 'draft', false, 7),
  ('20260000-0000-4000-8000-000000000021', '2026-brand-battle', 2, '', null, array['Each team may register up to 4 participants. Registration fee: ₹300 per team.', 'All participants must be students of a recognised college or educational institution.', 'Organisers assign each team a brand from a pair of competitors (for example, Coca-Cola and Pepsi, or Jio and Airtel). Teams may not change their assigned brand.', 'Teams receive preparation time before each debate. After the first round, teams get 10 minutes to prepare for the next match, including arguments and speaking order.', 'Each team defends its assigned brand and explains why it is better than its competitor. Discussion may cover brand strengths, product quality, customer appeal, market positioning, and competitive advantages.', 'Arguments must be relevant, logical, and supported by reasonable evidence.', 'All four team members are encouraged to contribute. Teams should divide speaking roles before the debate. No interrupting opponents outside the designated rebuttal period.', 'False information, personal attacks, offensive language, and inappropriate arguments are not allowed.', 'Mobile phones and internet access are not permitted during preparation unless the organisers explicitly allow them.', 'Knockout format: the winning team advances and the losing team is eliminated, until the finalists compete for the championship. Organisers may arrange preliminary matches or byes if needed.', 'Judges use the published scoring criteria, and the team with the higher score wins. In a tie, judges may ask both teams an additional question. The judges'' decision is final.']::text[], null, false, '/bizz%20words.jpg', 'Brand Battle thumbnail', 'Brand Battle', '', null, null, null, 'Brand Battle', 'TBA', 'General', null, 'none', null, 'draft', false, 8),
  ('20260000-0000-4000-8000-000000000022', '2026-bizz-war', 2, '', null, array['A team may have up to 4 members. Only registered members may take part, and every team member must attend.', 'Each team has 15 minutes to pitch, followed by 5 minutes for questions and answers.', 'The pitch should explain the problem, solution, target market, business model, what makes the idea different, finances, funding requested, and the share of the business offered in return.', 'A PowerPoint, prototype, or other visual aid is optional. The submission method, deadline, and file requirements will be decided later.', 'Only one person should speak at a time unless the judges ask otherwise.', 'Be professional, respect the judges, and arrive on time. Late teams may lose their slot.', 'Do not present copied ideas, illegal or unethical concepts, misleading claims, or offensive content.', 'Disqualification may occur for repeated time-limit violations, offensive content, rule-breaking, late reporting, or plagiarism.', 'Arrive 30 minutes early for registration, setup, and briefing.', 'Bring any laptop, charger, pen drive, or props you need. Organisers are not responsible for device problems. Tell organisers about special technical needs in advance.', 'Event photos and videos may be used for promotion. Your business idea remains your intellectual property.', 'Judging considers creativity, problem-solution fit, market understanding, feasibility, financial clarity, presentation skills, and teamwork. Scoring weights are not stated.', 'Funding is not guaranteed. The funding amount, selection process, timing, and terms are still to be decided.']::text[], 'https://chat.whatsapp.com/LlDgpiBb9BNL7Fcz8tmTpe', false, '/bizz%20words.jpg', 'Bizz-War thumbnail', 'Bizz-War', '', null, null, null, 'Bizz-War', 'TBA', 'General', null, 'none', null, 'draft', false, 9),
  ('20260000-0000-4000-8000-000000000023', '2026-sale-star', 2, '', null, array['Each participant randomly selects one product from the mystery box. Participants may not choose a product in advance or exchange the selected item.', 'Preparation: exactly 3 minutes to examine the product and prepare a pitch. Mobile phones, internet access, and outside assistance are not allowed during preparation.', 'Sales pitch: maximum 5 minutes to sell the assigned product to the judge. Participants may demonstrate the product and explain its usefulness, benefits, and value in their own approach, as long as the pitch stays relevant to the product.', 'The judge acts as a buyer and may ask questions, raise objections, or challenge the product''s value. The judge is not required to accept the offer.', 'The host gives a warning when about 1 minute remains. Participants must stop when selling time expires.', 'Use only the assigned product. Do not make false claims about its features, performance, or benefits. Offensive language, inappropriate behaviour, or deliberate disruption may lead to disqualification.', 'Judges apply the same criteria to all participants. The decision is based on the quality of the pitch, not confidence or entertainment value alone. The judges'' decision is final. In a tie, they may ask the tied participants one additional question.']::text[], null, false, '/case%20tho%20banta%20hai.jpg', 'Sale Star thumbnail', 'Sale Star', '', null, null, null, 'Sale Star', 'TBA', 'General', null, 'none', null, 'draft', false, 10)
